#!/usr/bin/env node
'use strict'

/**
 * Overlay the reviewed PrivacyTrace launcher icon set on a generated Tauri
 * Android resource tree.
 *
 * Source of truth: brand/android/res/** (checked in, Concept C kit v1.0).
 * Target:          apps/mobile/src-tauri/gen/android/app/src/main/res (ignored,
 *                  generated by `npm run android:prepare`).
 *
 * The overlay is intentionally strict: it refuses to run when the generated
 * template does not look like the tree pinned by this repository, and it
 * verifies the overlay afterwards instead of trusting a copy loop. It never
 * deletes unrelated generated resources.
 *
 * Static overlay only. Gradle builds and on-device launcher rendering are not
 * exercised by this script.
 */

const fs = require('node:fs')
const { parseXml } = require('./lib/android-xml.cjs')
const path = require('node:path')
const crypto = require('node:crypto')

const REPO_ROOT = path.resolve(__dirname, '..')
const DEFAULT_SOURCE_DIR = path.join(REPO_ROOT, 'brand', 'android', 'res')
const DEFAULT_RES_DIR = path.join(
  REPO_ROOT,
  'apps',
  'mobile',
  'src-tauri',
  'gen',
  'android',
  'app',
  'src',
  'main',
  'res'
)

const DENSITIES = ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']
const ADAPTIVE_XML_FILES = [
  'mipmap-anydpi-v26/ic_launcher.xml',
  'mipmap-anydpi-v26/ic_launcher_round.xml',
]
const EXPECTED_REFS = {
  background: '@drawable/ic_launcher_background',
  foreground: '@drawable/ic_launcher_foreground',
  monochrome: '@drawable/ic_launcher_monochrome',
}
const EXPECTED_DRAWABLE_FILES = [
  'drawable/ic_launcher_background.xml',
  'drawable/ic_launcher_foreground.xml',
  'drawable/ic_launcher_monochrome.xml',
]
const ANDROID_NS = 'http://schemas.android.com/apk/res/android'
const TEMP_PATTERN = /\.(?:tmp|temp|part|bak|orig)$/i

class ApplyError extends Error {}

function fail(message) {
  throw new ApplyError(message)
}

function isFile(target) {
  try {
    return fs.statSync(target).isFile()
  } catch {
    return false
  }
}

function isDirectory(target) {
  try {
    return fs.statSync(target).isDirectory()
  } catch {
    return false
  }
}

function toPosix(relativePath) {
  return relativePath.split(path.sep).join('/')
}

function fromPosix(relativePath) {
  return relativePath.split('/')
}

function sha256(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex')
}

function relativeToRepo(absolutePath) {
  return toPosix(path.relative(REPO_ROOT, absolutePath))
}

function readAdaptiveIcon(absolutePath, label) {
  let text
  try {
    text = fs.readFileSync(absolutePath, 'utf8')
  } catch (error) {
    fail(`${label}: cannot read file (${error.code || error.message})`)
  }
  const parsed = parseXml(text, label, (message) => fail(message))
  if (parsed.root !== 'adaptive-icon') {
    fail(`${label}: expected <adaptive-icon> root, found <${parsed.root}>`)
  }
  const root = parsed.elements[0]
  if (!root || root.attributes['xmlns:android'] !== ANDROID_NS) {
    fail(`${label}: missing xmlns:android="${ANDROID_NS}" on <adaptive-icon>`)
  }

  const layers = { background: null, foreground: null, monochrome: null }
  for (const element of parsed.elements.slice(1)) {
    if (element.parent !== 'adaptive-icon') {
      fail(`${label}: <${element.name}> is not a direct child of <adaptive-icon>`)
    }
    if (!Object.prototype.hasOwnProperty.call(layers, element.name)) {
      fail(`${label}: unexpected adaptive-icon child <${element.name}>`)
    }
    if (layers[element.name] !== null) {
      fail(`${label}: duplicate <${element.name}> in adaptive-icon`)
    }
    const drawable = element.attributes['android:drawable']
    if (!drawable) {
      fail(`${label}: <${element.name}> is missing android:drawable`)
    }
    layers[element.name] = drawable
  }
  return layers
}

function requireLayerRefs(layers, label, { requireMonochrome }) {
  for (const layer of ['background', 'foreground']) {
    if (!layers[layer]) fail(`${label}: missing <${layer}> layer`)
    if (layers[layer] !== EXPECTED_REFS[layer]) {
      fail(
        `${label}: <${layer}> references ${layers[layer]}, expected ${EXPECTED_REFS[layer]}`
      )
    }
  }
  if (requireMonochrome) {
    if (!layers.monochrome) fail(`${label}: missing <monochrome> layer`)
    if (layers.monochrome !== EXPECTED_REFS.monochrome) {
      fail(
        `${label}: <monochrome> references ${layers.monochrome}, expected ${EXPECTED_REFS.monochrome}`
      )
    }
  }
}

function drawableFileForRef(ref, label) {
  if (typeof ref !== 'string' || !ref.startsWith('@drawable/')) {
    fail(`${label}: expected a @drawable/ reference, found ${JSON.stringify(ref)}`)
  }
  const name = ref.slice('@drawable/'.length)
  if (!/^[a-z0-9_]+$/.test(name)) {
    fail(`${label}: invalid drawable resource name ${JSON.stringify(name)}`)
  }
  return `drawable/${name}.xml`
}

function verifyAdaptiveLayers(resDir, label) {
  const seen = new Set()
  for (const relativePath of ADAPTIVE_XML_FILES) {
    const absolutePath = path.join(resDir, ...fromPosix(relativePath))
    if (!isFile(absolutePath)) fail(`${label}: missing ${relativePath}`)
    const layers = readAdaptiveIcon(absolutePath, `${label}: ${relativePath}`)
    requireLayerRefs(layers, `${label}: ${relativePath}`, { requireMonochrome: true })
    for (const [layer, ref] of Object.entries(layers)) {
      const drawableRelativePath = drawableFileForRef(ref, `${label}: ${relativePath} <${layer}>`)
      const drawableAbsolutePath = path.join(resDir, ...fromPosix(drawableRelativePath))
      if (!isFile(drawableAbsolutePath)) {
        fail(
          `${label}: ${relativePath} <${layer}> references ${ref}, but ${drawableRelativePath} does not exist`
        )
      }
      seen.add(drawableRelativePath)
    }
  }
  return [...seen].sort()
}

function collectFiles(rootDir) {
  const files = []
  const walk = (currentDir, prefix) => {
    const entries = fs
      .readdirSync(currentDir, { withFileTypes: true })
      .sort((left, right) => left.name.localeCompare(right.name))
    for (const entry of entries) {
      const relativePath = prefix === '' ? entry.name : `${prefix}/${entry.name}`
      const absolutePath = path.join(currentDir, entry.name)
      if (entry.isDirectory()) {
        walk(absolutePath, relativePath)
      } else if (entry.isFile()) {
        files.push(relativePath)
      } else {
        fail(`Unsupported filesystem entry (not a regular file or directory): ${absolutePath}`)
      }
    }
  }
  walk(rootDir, '')
  return files.sort()
}

function validateGeneratedTemplate(resDir) {
  if (!fs.existsSync(resDir)) {
    fail(
      `Android resource directory not found: ${relativeToRepo(resDir)}\n` +
        'Run "npm run android:prepare" from apps/mobile first, or pass --res-dir <generated res directory>.'
    )
  }
  if (!isDirectory(resDir)) {
    fail(`Android resource path is not a directory: ${relativeToRepo(resDir)}`)
  }

  for (const relativePath of ADAPTIVE_XML_FILES) {
    const absolutePath = path.join(resDir, ...fromPosix(relativePath))
    if (!isFile(absolutePath)) {
      fail(
        `Generated Android template drifted: expected ${relativePath}, but it is missing.\n` +
          `Target: ${relativeToRepo(resDir)}\n` +
          'The Tauri template may have been renamed or the directory is not a generated Tauri res tree. ' +
          'Re-run "npm run tauri -- android init" and inspect the generated resources before retrying.'
      )
    }
    if (fs.statSync(absolutePath).size === 0) {
      fail(`Generated Android template drifted: ${relativePath} is empty. Delete gen/android and re-run "npm run android:prepare".`)
    }
    // Parse the template so malformed XML is reported before anything is copied.
    const layers = readAdaptiveIcon(absolutePath, `generated template: ${relativePath}`)
    if (!layers.background || !layers.foreground) {
      fail(
        `Generated Android template drifted: ${relativePath} does not declare both <background> and <foreground>.\n` +
          'Inspect the generated template before retrying; this script does not guess at new structure.'
      )
    }
  }

  const densityWithBitmap = DENSITIES.filter((density) =>
    isFile(path.join(resDir, `mipmap-${density}`, 'ic_launcher.png'))
  )
  if (densityWithBitmap.length === 0) {
    fail(
      'Generated Android template drifted: no mipmap-<density>/ic_launcher.png bitmap was found.\n' +
        `Target: ${relativeToRepo(resDir)}\n` +
        'Expected Tauri launcher resources (ic_launcher.png, ic_launcher_round.png) under at least one mipmap density. ' +
        'Inspect the generated template before retrying.'
    )
  }
  const emptyBitmap = densityWithBitmap.find(
    (density) => fs.statSync(path.join(resDir, `mipmap-${density}`, 'ic_launcher.png')).size === 0
  )
  if (emptyBitmap) {
    fail(
      `Generated Android template drifted: mipmap-${emptyBitmap}/ic_launcher.png is empty. ` +
        'Delete gen/android and re-run "npm run android:prepare".'
    )
  }
  return densityWithBitmap
}

function validateBrandSource(sourceDir) {
  if (!fs.existsSync(sourceDir)) {
    fail(
      `Brand Android icon source not found: ${relativeToRepo(sourceDir)}\n` +
        'Restore the checked-in brand/ assets before preparing the Android project.'
    )
  }
  if (!isDirectory(sourceDir)) {
    fail(`Brand Android icon source is not a directory: ${relativeToRepo(sourceDir)}`)
  }

  for (const relativePath of [...ADAPTIVE_XML_FILES, ...EXPECTED_DRAWABLE_FILES]) {
    const absolutePath = path.join(sourceDir, ...fromPosix(relativePath))
    if (!isFile(absolutePath)) {
      fail(`Brand Android icon source is incomplete: missing ${relativePath} (${relativeToRepo(sourceDir)})`)
    }
    if (fs.statSync(absolutePath).size === 0) {
      fail(`Brand Android icon source is incomplete: ${relativePath} is empty`)
    }
  }

  for (const density of DENSITIES) {
    for (const name of ['ic_launcher.png', 'ic_launcher_round.png']) {
      const relativePath = `mipmap-${density}/${name}`
      const absolutePath = path.join(sourceDir, ...fromPosix(relativePath))
      if (!isFile(absolutePath)) {
        fail(
          `Brand Android icon source is incomplete: missing ${relativePath}. ` +
            'Restore brand/android/res before preparing the Android project.'
        )
      }
      if (fs.statSync(absolutePath).size === 0) {
        fail(`Brand Android icon source is incomplete: ${relativePath} is empty`)
      }
    }
  }

  const unexpectedSourceFiles = collectFiles(sourceDir).filter(
    (relativePath) => !path.posix.basename(relativePath).startsWith('ic_launcher')
  )
  if (unexpectedSourceFiles.length > 0) {
    fail(
      'Brand Android icon source contains files outside the launcher icon namespace: ' +
        `${unexpectedSourceFiles.join(', ')}\n` +
        'Apply only overlays ic_launcher* resources; move unrelated drawables out of brand/android/res.'
    )
  }

  verifyAdaptiveLayers(sourceDir, 'brand/android/res')
}

function managedIconFiles(resDir, managedDirectories) {
  const files = []
  for (const directory of managedDirectories) {
    const absoluteDirectory = path.join(resDir, directory)
    if (!isDirectory(absoluteDirectory)) {
      fail(`Overlay verification failed: expected directory ${relativeToRepo(absoluteDirectory)} is missing`)
    }
    for (const entry of fs.readdirSync(absoluteDirectory, { withFileTypes: true })) {
      if (entry.isFile() && entry.name.startsWith('ic_launcher')) {
        files.push(`${directory}/${entry.name}`)
      }
    }
  }
  return files.sort()
}

function verifyOverlay(resDir, sourceDir, sourceFiles) {
  const expected = new Set(sourceFiles)

  const missing = sourceFiles.filter(
    (relativePath) => !isFile(path.join(resDir, ...fromPosix(relativePath)))
  )
  if (missing.length > 0) {
    fail(
      `Overlay verification failed: ${missing.length} brand file(s) were not written to the generated tree.\n` +
        `Missing: ${missing.join(', ')}`
    )
  }

  const managedDirectories = [...new Set(sourceFiles.map((relativePath) => relativePath.split('/')[0]))].sort()
  const actual = managedIconFiles(resDir, managedDirectories)
  const unexpected = actual.filter((relativePath) => !expected.has(relativePath))
  if (unexpected.length > 0) {
    fail(
      'Overlay verification failed: generated template contains launcher resources that are not part of brand/android/res.\n' +
        `Unexpected: ${unexpected.join(', ')}\n` +
        'Inspect the generated template or update brand/android/res; this script does not delete unrelated generated files.'
    )
  }

  const byteMismatches = []
  for (const relativePath of sourceFiles) {
    const sourceBytes = fs.readFileSync(path.join(sourceDir, ...fromPosix(relativePath)))
    const targetBytes = fs.readFileSync(path.join(resDir, ...fromPosix(relativePath)))
    if (!sourceBytes.equals(targetBytes)) {
      byteMismatches.push(`${relativePath} (source sha256 ${sha256(sourceBytes)}, target sha256 ${sha256(targetBytes)})`)
    }
  }
  if (byteMismatches.length > 0) {
    fail(
      'Overlay verification failed: copied files are not byte-identical to brand/android/res.\n' +
        byteMismatches.join('\n')
    )
  }

  verifyAdaptiveLayers(resDir, 'generated res')

  const leftovers = collectFiles(resDir).filter((relativePath) => TEMP_PATTERN.test(relativePath))
  if (leftovers.length > 0) {
    fail(
      'Overlay verification failed: temporary files were left behind in the generated res tree.\n' +
        leftovers.join('\n')
    )
  }

  return {
    fileSet: actual.length,
    byteIdentical: sourceFiles.length,
    adaptiveXml: ADAPTIVE_XML_FILES.length,
    temporaryFiles: 0,
  }
}

/**
 * Apply the brand overlay and verify the result.
 *
 * @param {{ resDir?: string, sourceDir?: string }} [options]
 * @returns {{ sourceDir: string, resDir: string, total: number, copied: number, unchanged: number, verified: object }}
 */
function applyBrandAndroidIcons(options = {}) {
  const resDir = path.resolve(options.resDir || DEFAULT_RES_DIR)
  const sourceDir = path.resolve(options.sourceDir || DEFAULT_SOURCE_DIR)

  validateGeneratedTemplate(resDir)
  validateBrandSource(sourceDir)

  const sourceFiles = collectFiles(sourceDir)
  if (sourceFiles.length === 0) {
    fail(`Brand Android icon source is empty: ${relativeToRepo(sourceDir)}`)
  }

  let copied = 0
  let unchanged = 0
  for (const relativePath of sourceFiles) {
    const sourcePath = path.join(sourceDir, ...fromPosix(relativePath))
    const targetPath = path.join(resDir, ...fromPosix(relativePath))
    try {
      fs.mkdirSync(path.dirname(targetPath), { recursive: true })
    } catch (error) {
      fail(`Cannot create target directory for ${relativePath}: ${error.message}`)
    }
    if (fs.existsSync(targetPath) && !isFile(targetPath)) {
      fail(`Cannot overlay ${relativePath}: target exists but is not a regular file`)
    }

    const sourceBytes = fs.readFileSync(sourcePath)
    if (isFile(targetPath)) {
      const targetBytes = fs.readFileSync(targetPath)
      if (sourceBytes.equals(targetBytes)) {
        unchanged += 1
        continue
      }
    }
    try {
      fs.copyFileSync(sourcePath, targetPath)
    } catch (error) {
      fail(`Failed to copy ${relativePath}: ${error.message}`)
    }
    copied += 1
  }

  const verified = verifyOverlay(resDir, sourceDir, sourceFiles)
  return { sourceDir, resDir, total: sourceFiles.length, copied, unchanged, verified }
}

const USAGE = `Usage: node scripts/apply-brand-android-icons.cjs [options]

Overlay the checked-in PrivacyTrace launcher icons (brand/android/res/**) onto
the generated Tauri Android resource tree.

Options:
  --res-dir <path>  Generated res directory to overlay.
                    Default: apps/mobile/src-tauri/gen/android/app/src/main/res
  -h, --help        Show this help and exit.

Behavior:
  * Requires a generated Tauri res tree with mipmap-anydpi-v26/ic_launcher.xml,
    mipmap-anydpi-v26/ic_launcher_round.xml, and at least one
    mipmap-<density>/ic_launcher.png. Missing or renamed template resources are
    reported as errors; the script never silently skips files.
  * Copies brand/android/res/** over the target, then verifies the launcher file
    set, byte equality, and adaptive-icon @drawable references.
  * Re-running is idempotent: byte-identical files are left untouched and no
    temporary files are created.
  * Unrelated generated resources (values/, xml/, other drawables) are preserved.

Typical use:
  cd apps/mobile
  npm run android:prepare

Static overlay only: this does not run Gradle, does not render the launcher on a
device, and does not verify round/themed icon appearance. Those remain NOT_RUN.
`

function parseArgs(argv) {
  const options = { help: false, resDir: null }
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index]
    if (argument === '--help' || argument === '-h') {
      options.help = true
      continue
    }
    if (argument === '--res-dir') {
      const value = argv[index + 1]
      if (!value || value.startsWith('-')) {
        fail('--res-dir requires a directory path. Run with --help for usage.')
      }
      options.resDir = value
      index += 1
      continue
    }
    if (argument.startsWith('--res-dir=')) {
      const value = argument.slice('--res-dir='.length)
      if (!value) fail('--res-dir requires a directory path. Run with --help for usage.')
      options.resDir = value
      continue
    }
    fail(`Unknown argument: ${argument}. Run with --help for usage.`)
  }
  return options
}

function main() {
  let options
  try {
    options = parseArgs(process.argv.slice(2))
  } catch (error) {
    if (!(error instanceof ApplyError)) throw error
    console.error(`[apply-brand-android-icons] ERROR: ${error.message}`)
    process.exitCode = 2
    return
  }

  if (options.help) {
    process.stdout.write(USAGE)
    return
  }

  try {
    const result = applyBrandAndroidIcons({ resDir: options.resDir || DEFAULT_RES_DIR })
    console.log(`[apply-brand-android-icons] source: ${relativeToRepo(result.sourceDir)}`)
    console.log(`[apply-brand-android-icons] target: ${relativeToRepo(result.resDir)}`)
    console.log(
      `[apply-brand-android-icons] ${result.total} launcher resource(s): ` +
        `${result.copied} copied, ${result.unchanged} already identical`
    )
    console.log(
      `[apply-brand-android-icons] verified: file set (${result.verified.fileSet}), ` +
        `byte equality (${result.verified.byteIdentical}), ` +
        `adaptive icon XML (${result.verified.adaptiveXml}), ` +
        `temporary files (${result.verified.temporaryFiles})`
    )
    console.log('[apply-brand-android-icons] Gradle build / device launcher rendering: NOT_RUN')
  } catch (error) {
    if (!(error instanceof ApplyError)) throw error
    console.error(`[apply-brand-android-icons] ERROR: ${error.message}`)
    process.exitCode = 1
  }
}

module.exports = {
  APPLY_HELP: USAGE,
  ApplyError,
  DEFAULT_RES_DIR,
  DEFAULT_SOURCE_DIR,
  applyBrandAndroidIcons,
}

if (require.main === module) main()
